fn thrown(e:Box<dyn std::any::Any+Send>)->String{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");for name in ["NullPointerException","ClassCastException","IllegalStateException","StringIndexOutOfBoundsException","RuntimeException"]{if s.starts_with(name){return name.into();}}if s.contains("index out of bounds"){return "ArrayIndexOutOfBoundsException".into();}format!("panic: {s}")}
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>json!({"result":thrown(e)})}}
fn hex(b:&[u8])->String{b.iter().map(|b|format!("{b:02x}")).collect()}
fn bytes(f:impl FnOnce(&mut dyn LittleEndianOutput)->Value)->Value{let mut out=LittleEndianByteArrayOutput::new();let r=call(||f(&mut out));let mut r=r;r["bytes"]=json!(hex(&out.get_bytes()));r}
fn object(p:&Value)->NullableObject{match p["kind"].as_str().unwrap(){"null"=>None,"number"=>Some(Rc::new(f64::from_bits(u64::from_str_radix(p["bits"].as_str().unwrap(),16).unwrap()))),"boolean"=>Some(Rc::new(p["value"].as_bool().unwrap())),"integer"=>Some(Rc::new(p["value"].as_i64().unwrap()as i32)),"error"=>Some(ErrorConstant::valueOf(p["value"].as_i64().unwrap()as i32)),_=>Some(Rc::new(p["value"].as_str().unwrap().to_string()))}}
