fn value(v:&ValueRef)->Value{if let Some(r)=v.as_ref_eval(){return json!({"kind":"ref","sheet":r.getSheetIndex(),"row":r.getRow(),"col":r.getColumn(),"inner":value(&r.getInnerValueEval().ok().unwrap().unwrap())});}if let Some(n)=v.as_any().downcast_ref::<NumberEval>(){let n=n.getNumberValue();return json!({"kind":"number","bits":format!("{:016x}",if n.is_nan(){0x7ff8000000000000}else{n.to_bits()})});}if let Some(s)=v.as_any().downcast_ref::<StringEval>(){return json!({"kind":"string","value":String::from_utf16(s.getStringValue()).unwrap()});}if let Some(b)=v.as_any().downcast_ref::<BoolEval>(){return json!({"kind":"boolean","value":b.getBooleanValue()});}if let Some(e)=v.as_any().downcast_ref::<ErrorEval>(){return json!({"kind":"error","code":e.getErrorCode()});}if v.as_any().is::<BlankEval>(){return json!({"kind":"blank"});}panic!("unexpected observed value")}
fn books(input:&Value)->Value{let mut rows=vec![];for mode in 0..5{let count=if mode==4{input["urls"].as_array().unwrap().len()}else{1};for i in 0..count{let mut row=json!({"mode":mode,"case":i});let names:SheetNames=Rc::new(RefCell::new(vec![Some("Cache".into()),Some("第二表😀".into())]));let mut holder=None;let made=call(||{holder=Some(match mode{0=>SupBookRecord::createAddInFunctions(),1=>SupBookRecord::createNullSupBook(-32768),2=>SupBookRecord::createEmptySupBook(),3=>SupBookRecord::createSameSheetRef(),_=>SupBookRecord::createExternalReferences(input["urls"][i].as_str(),Some(names.clone()))});true});row["made"]=made;if let Some(b)=holder{row["addIn"]=json!(b.isAddInFunctions());row["external"]=json!(b.isExternalReferences());row["internal"]=json!(b.isInternalReferences());row["empty"]=json!(b.isEmptySupBook());row["nullBook"]=json!(b.isNullSupBook());row["same"]=json!(b.isSameSheetRef());row["text"]=json!(b.toString());row["url"]=call(||b.getURL());row["names"]=call(||b.getSheetNames());row["size"]=call(||b.getDataSize());row["data"]=bytes(|o|{b.serializeData(o);Value::Null});if mode==4{let mut copy=b.getSheetNames();copy[0]=Some("copy".into());row["copiedArray"]=json!(b.getSheetNames()[0].as_deref()!=Some("copy"));names.borrow_mut()[0]=Some("aliased".into());row["inputAlias"]=json!(b.getSheetNames()[0].as_deref()==Some("aliased"));}b.setNumberOfSheets(-1);row["changedCount"]=json!(b.getNumberOfSheets()as i32);row["sid"]=json!(b.getSid()as i32);}rows.push(row);}}json!(rows)}
