fn refs(book:&Rc<KmoBook>,ebb:Rc<ExternalBookBlock>)->Value{let lt=book.getLinkTable();lt.borrow_mut().resetExternalLink(Some(&[ebb]));let ext=lt.borrow_mut().checkExternalSheetIndex(Some("cached.xlsx"),Some("Cache"));let mut rows=vec![];for version in [97,2007]{let sv=if version==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007};book.setSpreadsheetVersion(sv);for col in 1..=7{let mut data=vec![58];data.extend_from_slice(&(ext as i16).to_le_bytes());if version==97{data.extend_from_slice(&2i16.to_le_bytes());}else{data.extend_from_slice(&2i32.to_le_bytes());}data.extend_from_slice(&(col as i16).to_le_bytes());let ew:Rc<dyn IEvalWorkbook>=Rc::new(EvaluationWorkbook::EvaluationWorkbook(book));let we=Rc::new(WorkbookEvaluator::WorkbookEvaluator(ew.clone()));let mut ec=EvaluationContext::EvaluationContext(we.clone(),ew,0,1,1,false);let bytes=value(WorkbookBytesEvaluator::WorkbookBytesEvaluator(we.clone()).evaluateFormula(&mut ec,&data,data.len()as i32).ok().unwrap().front().unwrap());let ptg=value(&we.getEvalForOperandPtg(&Ptg::readTokens(data.len()as i32,&data,sv)[0],&mut ec).ok().unwrap());rows.push(json!({"version":version,"col":col,"bytes":bytes,"ptg":ptg}));}}book.setSpreadsheetVersion(SpreadsheetVersion::EXCEL2007);json!(rows)}
